def to_documents(apps, schema_editor):
    """Plain-text descriptions become HTML; the old per-item log is appended to it."""
    from html import escape

    from board.document import from_text, heading

    Comment = apps.get_model("board", "Comment")
    Item = apps.get_model("board", "Item")
    Entry = apps.get_model("board", "Entry")
    Comment.objects.filter(resolved=True).update(status="resolved")
    kinds = {"observation": "Observation", "orientation": "Orientation", "decision": "Decision",
             "action": "Action", "note": "Note"}
    for item in Item.objects.all():
        html = from_text(item.body)
        entries = Entry.objects.filter(item=item).select_related("author").order_by("created_at")
        if entries:
            html += heading("Log")
            for e in entries:
                who = e.author.name if e.author else ""
                when = e.created_at.strftime("%Y-%m-%d")
                text = escape(e.body).replace("\n", "<br>")
                html += f"<p><strong>{kinds.get(e.kind, e.kind)}</strong> — {text} <em>({escape(who)}, {when})</em></p>"
            entries.delete()
        item.body = html
        item.save(update_fields=["body"])


